WITH row AS (INSERT INTO zc_private.discord_guild_config(guild_id,linked_role_id) VALUES($1,$2) ON CONFLICT(guild_id) DO UPDATE SET linked_role_id=excluded.linked_role_id,date_updated=clock_timestamp() RETURNING *) SELECT jsonb_build_object('guildId',guild_id::text,'linkedRoleId',CASE WHEN linked_role_id IS NULL THEN NULL ELSE to_jsonb(linked_role_id::text) END,'dateCreated',to_char(date_created AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),'dateUpdated',to_char(date_updated AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')) AS value FROM row
